zugewinnausgleich_drittersatz_mit_gesamtschuld <- function(ausgleichsforderung=NULL, endnettovermoegen=NULL, bereicherungsrechtlicher_zuwendungswert=NULL, anrechenbare_entreicherung=NULL, erfuellung_ehegatte=NULL, erfuellung_dritter=NULL, begrenzungsmodell=NULL, methodennachweis=NULL) {
 forderung <- .geld(ausgleichsforderung);netto <- .zahleneingabe(endnettovermoegen);ehegatte <- .geld(erfuellung_ehegatte);dritter <- .geld(erfuellung_dritter);.text(methodennachweis,'methodennachweis');.auswahl(begrenzungsmodell,'begrenzungsmodell',c('ausgleichsforderung_als_obergrenze'))
 kleiner <- function(x,y) if(.vergleichen(x,y)<0)x else y
 ber <- .geld(bereicherung_entreicherungsrest(bereicherungsrechtlicher_zuwendungswert,anrechenbare_entreicherung,methodennachweis)$wert);merkmal <- .vergleichen(forderung,netto)>0;grund <- if(merkmal)kleiner(ber,forderung) else .bruch(0);erfuellt <- .addieren(ehegatte,dritter)
 if(.vergleichen(erfuellt,forderung)>0||.vergleichen(dritter,grund)>0) .fehler('erfuellungen','Erf\u00fcllungen h\u00f6chstens gemeinsame Forderung; Dritterf\u00fcllung h\u00f6chstens Drittgrundbetrag.')
 rest <- .subtrahieren(forderung,erfuellt);dritt <- kleiner(rest,.subtrahieren(grund,dritter));fehl <- .subtrahieren(forderung,netto)
 if(.vergleichen(fehl,.bruch(0))<0) fehl <- .bruch(0)
 wert <- list(betragsmerkmal_erfuellt=merkmal,vermoegensfehlbetrag=.bruchteile(fehl),bereicherungsrest=.bruchteile(ber),drittgrundbetrag=.bruchteile(grund),gemeinsame_restforderung=.bruchteile(rest),verbleibender_drittersatz=.bruchteile(dritt))
 eingaben <- list(ausgleichsforderung=ausgleichsforderung, endnettovermoegen=endnettovermoegen, bereicherungsrechtlicher_zuwendungswert=bereicherungsrechtlicher_zuwendungswert, anrechenbare_entreicherung=anrechenbare_entreicherung, erfuellung_ehegatte=erfuellung_ehegatte, erfuellung_dritter=erfuellung_dritter, begrenzungsmodell=begrenzungsmodell, methodennachweis=methodennachweis)
 ergebnis <- .ergebnis(wert,"EUR","BGB_ZUGEWINNAUSGLEICH_DRITTERSATZ_MIT_GESAMTSCHULD",eingaben,list(list(operation="Verm\u00f6gensfehlbetrag als Tatbestandsvergleich bestimmen, qualifizierten Bereicherungsrest auf Forderung begrenzen und gemeinsame Erf\u00fcllungen ohne Doppelabzug verrechnen.")),eingaben)
 ergebnis$hinweise <- list("Bedingtes1390-Geldersatzmodell mit ausdr\u00fccklich qualifizierter Forderungsobergrenze: Tatbestandsmerkmal urspr\u00fcnglicheAusgleichsforderung>Endnettoverm\u00f6gen selbst vergleichen. Bereicherungsrest durch vorhandenen818-Kern. Drittgrundbetrag bei erf\u00fclltem Betragsmerkmal=min(Bereicherungsrest,urspr\u00fcnglicheAusgleichsforderung), nicht min(...,Verm\u00f6gensfehlbetrag). Rechtliche Geltung dieser Forderungsobergrenze wird als Voraussetzung verlangt, nicht abschlie\u00dfend aus der Reformbegr\u00fcndung2009 behauptet. Beide Erf\u00fcllungsbetr\u00e4ge einmal von der gemeinsamen Forderung abziehen; Drittrest=min(noch offener gemeinsamer Forderung,Drittgrundbetrag-Dritterf\u00fcllung). Ehegattenzahlung verkleinert die gemeinsame Restforderung, ist aber nicht zus\u00e4tzlich nochmals vom individuellen Drittrahmen abzuziehen. Urspr\u00fcngliches Betragsmerkmal nicht nachtr\u00e4glich anhand der bereits getilgten Forderung neu pr\u00fcfen. Keine \u00fcber den urspr\u00fcnglichen Anspruch hinausgehenden Nebenforderungen; Sachherausgabe zur Abwendung nur bei rechtlich bestimmter Erf\u00fcllungsbewertung als Erf\u00fcllungsbetrag erfassen. \u00a71390III-Verj\u00e4hrungsbeginn bleibt separate Kalenderbindung.")
 ergebnis
}
